#!/bin/sh
# Re-run from the lore worktree (so `ocx package exec` resolves): sh run.sh
# Uses the full conan_toolchain.cmake generated by Conan 2.32.0 (profile cppstd=17) in tc17/.
S=/home/mherwig/.cache/cmake-measure-scratch/verify-package-managers/cppstd
NINJA=$(ocx package exec ninja-build/ninja -- sh -c "command -v ninja")
WFLAG=${WFLAG:--Werror=dev}
for v in 3.31 4.3 4.4; do
  for m in none set20 guarded20 feature20 cli20; do
    extra=""; mm=$m
    if [ "$m" = cli20 ]; then extra="-DCMAKE_CXX_STANDARD=20"; mm=none; fi
    B="$S/b-$v-$m"; rm -rf "$B"
    ocx package exec kitware/cmake:$v -- cmake -S "$S/proj" -B "$B" -G Ninja \
      -DCMAKE_TOOLCHAIN_FILE="$S/tc17/conan_toolchain.cmake" \
      -DCMAKE_CXX_COMPILER="$S/zigcxx.sh" -DCMAKE_MAKE_PROGRAM="$NINJA" -DMODE=$mm $extra $WFLAG > "$B.log" 2>&1
    rc=$?
    w=$(grep -c 'has been modified to' "$B.log")
    std=$(grep -o -e '-std=[a-z+0-9]*' "$B/build.ninja" 2>/dev/null | sort -u | tr '\n' ' ')
    ver=$(grep -m1 -o 'cmake version [0-9.]*' "$B.log")
    echo "cmake $v mode=$m rc=$rc watchlines=$w std=$std"
  done
done
